    // Helper to get I'rab
    fun getAyahIrab(surahNumber: Int, ayahNumber: Int, fallbackText: String): String {
        val specific = irabDatabase[surahNumber to ayahNumber]
        if (specific != null) return specific

        // Analytical fallback template with standard grammatical roles
        return generateGeneralIrab(surahNumber, ayahNumber, fallbackText)
    }

    // Helper to get Tafsir
    fun getAyahTafsir(surahNumber: Int, ayahNumber: Int, existingTafsir: String): String {
        if (existingTafsir.isNotBlank() && existingTafsir != "تلاوة وقراءة سورة مباركة كاملة بفضل الله.") {
            return existingTafsir
        }
        val offlineAyah = QuranOfflineData.getOfflineSurahAyahs(surahNumber)?.find { it.numberInSurah == ayahNumber }
        if (offlineAyah != null && offlineAyah.tafsirShort.isNotBlank()) {
            return offlineAyah.tafsirShort
        }
        return "تفسير وتدبر الآية الكريمة رقم ($ayahNumber) من سورة مباركة: بيان المعاني السامية، الأحكام الشرعية، والدلالات الإيمانية التي ترشد المؤمن لصراط الله المستقيم وتثبت قلبه بالإيمان."
    }

    private fun generateGeneralIrab(surahNumber: Int, ayahNumber: Int, text: String): String {
        val words = text.split(" ").filter { it.isNotBlank() }
        val sb = StringBuilder()
        sb.append("• إعراب الآية الكريمة (${ayahNumber}):\n")
        
        if (words.isNotEmpty()) {
            val firstWord = words.first().replace(Regex("[۞۩۝0-9\\p{Punct}]"), "")
            sb.append("• [").append(firstWord).append("]: تبتدئ به الجملة الكريمة بحسب موقعه الإعرابي (اسم مبتدأ، أو فعل أمر/ماضٍ/مضارع، أو حرف استئتاح/قسم/توكيد).\n")
        }
        
        sb.append("• الجملة القرآنية: جملة محكمة تشتمل على الأركان الأساسية من عُمد وفضلات (فعل وفاعل ومفعول به، أو مبتدأ وخبر)، ومتعلقات الجار والمجرور التابعة لمعاني التنزيل الحكيم والتأكيد البياني الإعجازي.")
        return sb.toString()
    }
}
